            "<span style=\"color:#B392F0\">          android:value</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"@bool/email_address_required\"</span><span style=\"color:#E1E4E8\">/&gt;</span>",
