            "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { GooglePayEventsEnum, Stripe } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor-community/stripe'</span><span style=\"color:#E1E4E8\">;</span>",
            "",
            "<span style=\"color:#E1E4E8\">(</span><span style=\"color:#F97583\">async</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#F97583\">  try</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#F97583\">    await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">isGooglePayAvailable</span><span style=\"color:#E1E4E8\">();</span>",
            "<span style=\"color:#E1E4E8\">  } </span><span style=\"color:#F97583\">catch</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#F97583\">    return</span><span style=\"color:#E1E4E8\">;</span>",
            "<span style=\"color:#E1E4E8\">  }</span>",
            "",
            "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(GooglePayEventsEnum.Completed, () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#E1E4E8\">    console.</span><span style=\"color:#B392F0\">log</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'GooglePayEventsEnum.Completed'</span><span style=\"color:#E1E4E8\">);</span>",
            "<span style=\"color:#E1E4E8\">  });</span>",
            "",
            "<span style=\"color:#a0aab5\">  // Replace `/your-intent-endpoint` with your backend from Server Integration.</span>",
            "<span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> response</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> fetch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'/your-intent-endpoint'</span><span style=\"color:#E1E4E8\">, {</span>",
            "<span style=\"color:#E1E4E8\">    method: </span><span style=\"color:#9ECBFF\">'POST'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">  });</span>",
            "<span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">response.ok) {</span>",
            "<span style=\"color:#F97583\">    throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`Intent request failed: ${</span><span style=\"color:#E1E4E8\">response</span><span style=\"color:#9ECBFF\">.</span><span style=\"color:#E1E4E8\">status</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span>",
            "<span style=\"color:#E1E4E8\">  }</span>",
            "<span style=\"color:#F97583\">  const</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#79B8FF\">paymentIntent</span><span style=\"color:#E1E4E8\"> } </span><span style=\"color:#F97583\">=</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> response.</span><span style=\"color:#B392F0\">json</span><span style=\"color:#E1E4E8\">()) </span><span style=\"color:#F97583\">as</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#FFAB70\">    paymentIntent</span><span style=\"color:#F97583\">:</span><span style=\"color:#79B8FF\"> string</span><span style=\"color:#E1E4E8\">;</span>",
            "<span style=\"color:#E1E4E8\">  };</span>",
            "",
            "<span style=\"color:#a0aab5\">  // Prepare Google Pay</span>",
            "<span style=\"color:#F97583\">  await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">createGooglePay</span><span style=\"color:#E1E4E8\">({</span>",
            "<span style=\"color:#E1E4E8\">    paymentIntentClientSecret: paymentIntent,</span>",
            "",
            "<span style=\"color:#a0aab5\">    // Web only. Google Pay on Android App doesn't need</span>",
            "<span style=\"color:#E1E4E8\">    paymentSummaryItems: [{</span>",
            "<span style=\"color:#E1E4E8\">      label: </span><span style=\"color:#9ECBFF\">'Product Name'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">      amount: </span><span style=\"color:#79B8FF\">1099.00</span>",
            "<span style=\"color:#E1E4E8\">    }],</span>",
            "<span style=\"color:#E1E4E8\">    merchantIdentifier: </span><span style=\"color:#9ECBFF\">'merchant.com.getcapacitor.stripe'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">    countryCode: </span><span style=\"color:#9ECBFF\">'US'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">    currency: </span><span style=\"color:#9ECBFF\">'USD'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">  });</span>",
            "",
            "<span style=\"color:#a0aab5\">  // Present Google Pay</span>",
            "<span style=\"color:#F97583\">  const</span><span style=\"color:#79B8FF\"> result</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#E1E4E8\"> Stripe.</span><span style=\"color:#B392F0\">presentGooglePay</span><span style=\"color:#E1E4E8\">();</span>",
            "<span style=\"color:#F97583\">  if</span><span style=\"color:#E1E4E8\"> (result.paymentResult </span><span style=\"color:#F97583\">===</span><span style=\"color:#E1E4E8\"> GooglePayEventsEnum.Completed) {</span>",
            "<span style=\"color:#a0aab5\">    // Update UI only. Fulfill orders from a verified server webhook.</span>",
            "<span style=\"color:#E1E4E8\">  }</span>",
            "<span style=\"color:#E1E4E8\">})();</span>",
            ""
